    groups={}
    for r in data['prompts']:
        key=(r['topic']+'|'+r['length'], bool(r['judge_win']))
        groups.setdefault(key,[]).append(r['id'])
    ids=[]
    per=6 if arena=='dev' else 7
    for key in sorted(groups):
        arr=groups[key]
        # deterministic spread across the cell, avoiding dependence on prompt order as much as possible
        if len(arr)<=per:
            sel=arr
        else:
            sel=[arr[int((i+0.5)*len(arr)/per)] for i in range(per)]
        ids.extend(sel)
    out=json.loads(subprocess.check_output(['/app/bin/lab','label',f'arena={arena}','ids='+json.dumps(ids)]))
    print(arena, 'requested', len(ids), 'got', len(out))
    labels_all[arena]={'ids':ids,'labels':out}
print(json.dumps(labels_all, indent=2, sort_keys=True))
